import { createContext, useContext } from 'react'

export interface FieldContextValue {
  /** The id the `<label for>` points at. Generated by Field, consumed by the
   *  control, so the two are never written by hand and never drift. */
  id: string
  /** Ids of the hint and error paragraphs, or undefined when there are none. */
  describedBy: string | undefined
  invalid: boolean
  required: boolean
}

export const FieldContext = createContext<FieldContextValue | null>(null)

/**
 * Read the surrounding Field, if there is one.
 *
 * Returns null rather than throwing so a control stays usable outside a Field —
 * an inline search box in a topbar has no label, and requiring a dummy wrapper
 * around it would be worse than the control simply not claiming an association.
 */
export function useFieldControl(): FieldContextValue | null {
  return useContext(FieldContext)
}
